request.user_message:
Abstract the following semantic predicate cluster into exactly one reusable predicate.

Cluster ID:
binary-009

Cluster Arity:
2

Cluster Members:
[
  {
    "name": "DERIVES_CONSTRAINT_INPUTS_FROM_OBSERVED_RECORDS",
    "definition": "The reasoning extracts specific values from the content of an observation and transforms them into derived quantities, such as occupied intervals, ranges, totals, or parsed records, that serve as inputs constraining the subsequent solution or decision.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning text that extracts values from observed records and computes derived quantities from them."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation whose content supplies the underlying records or values being transformed."
      }
    ],
    "assertion_conditions": [
      "The reasoning cites or transforms specific content present in the observation.",
      "The derived quantities are used as inputs to the subsequent constraint evaluation or decision rather than merely described."
    ],
    "exclusion_conditions": [
      "The reasoning discusses the observation only in general terms without extracting concrete values.",
      "The observation's content is not used in the derived quantities.",
      "The reasoning only restates the observation's content without computing anything from it."
    ]
  },
  {
    "name": "DERIVES_EXACTNESS_CONSTRAINT_FROM_MEASUREMENT",
    "definition": "The reasoning extracts a precise measurable or formatting property from an observation and adopts preservation of that property as a requirement for a subsequent action or acceptance check.",
    "parameters": [
      {
        "name": "measurement_observation",
        "type": "observation",
        "description": "The observation reporting an exact quantitative or formatting property such as byte count, hash, whitespace pattern, or exact text layout."
      },
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning that refers to the precise property as a requirement to be matched or preserved."
      }
    ],
    "assertion_conditions": [
      "The observation provides a precise measurable, byte-level, or formatting property.",
      "The reasoning explicitly refers to that property as something that must be matched or preserved.",
      "The property is used as a constraint on a subsequent action or as an acceptance criterion."
    ],
    "exclusion_conditions": [
      "The observation provides only qualitative or approximate information.",
      "The reasoning does not impose preservation or matching of the measured property.",
      "The measured property is mentioned but not used as a requirement or acceptance criterion."
    ]
  },
  {
    "name": "COMPARES_MEASURED_VALUE_AGAINST_THRESHOLD",
    "definition": "The reasoning extracts a quantitative measurement reported in an observation and evaluates it against a stated limit, threshold, or required magnitude, asserting that the measured value satisfies or violates that requirement; the evaluation may also characterize the size or adequacy of the margin between the measurement and the threshold.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node that restates the reported measurement and evaluates it against the limit or requirement."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation reporting the numeric measurement being evaluated."
      }
    ],
    "assertion_conditions": [
      "The observation contains a numeric value produced by a measurement, timing, or count.",
      "The reasoning explicitly relates that value to a stated limit, threshold, or required magnitude and asserts compliance or violation."
    ],
    "exclusion_conditions": [
      "The observation provides only qualitative information and no numeric comparison is made.",
      "The reasoning reports the numeric value without linking it to any limit or requirement.",
      "The reasoning compares quantities with each other without invoking a required limit or threshold."
    ]
  },
  {
    "name": "VALIDATES_RESULT_AGAINST_EXPECTED_RELATIONS",
    "definition": "The reasoning checks reported result values against structural relations that must hold among them given the definitions of the compared scopes or categories, and uses agreement or violation of those relations to judge the plausibility of the results.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text checking reported values against expected containment, monotonicity, or aggregation relations."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation supplying the result values being checked."
      }
    ],
    "assertion_conditions": [
      "The observation reports numeric values for several related categories or scopes.",
      "The reasoning states a relationship that the values must satisfy given the scope definitions, such as nested-scope containment, monotonic ordering across widening periods, or sum equality with a grand total.",
      "The reasoning concludes that the values are consistent with, or violate, those relationships."
    ],
    "exclusion_conditions": [
      "The reasoning merely restates the reported values without invoking any expected relationship among them.",
      "The invoked relationship is not implied by the definitions of the compared scopes.",
      "The reasoning performs an independent recomputation instead of an internal consistency check."
    ]
  },
  {
    "name": "ASSESSES_CANDIDATE_AGAINST_CONSTRAINTS",
    "definition": "The reasoning considers an identifiable candidate value, fragment, or occurrence supplied by observed content and evaluates whether it satisfies one or more explicitly stated requirements, reaching a judgment of compliance, partial compliance, or violation; the candidate may be a value assembled from multiple observed fragments, and the judgment may draw on the candidate's observed surrounding context.",
    "parameters": [
      {
        "name": "assessment_reasoning",
        "type": "reasoning",
        "description": "The reasoning that evaluates the candidate against the stated requirements."
      },
      {
        "name": "candidate_evidence",
        "type": "observation",
        "description": "The observation containing the candidate value, an observed fragment of it, or the surrounding context from which the candidate is extracted or assembled."
      }
    ],
    "assertion_conditions": [
      "The observation contains an identifiable candidate value, fragment, or occurrence, or content from which the candidate is assembled.",
      "The assessment_reasoning refers to at least one explicit requirement and compares the candidate to it.",
      "The reasoning reaches a conclusion about compliance, partial compliance, or noncompliance; noncompliance may include rejecting a spurious occurrence because its observed adjacent context violates the required format or character set."
    ],
    "exclusion_conditions": [
      "The reasoning only extracts or repeats the candidate without evaluating requirements.",
      "No explicit requirement is applied to the candidate.",
      "The observation does not contain the candidate or the context used to assess it.",
      "The reasoning evaluates a requirement or deliverable independently of any candidate value."
    ]
  },
  {
    "name": "CORROBORATES_CANDIDATE_WITH_INDEPENDENT_METADATA",
    "definition": "Reasoning uses a separately recorded metadata value, such as a length, size, count, or structural field, that is independent of a proposed candidate's own expression to check the candidate's consistency and thereby corroborate or undermine it.",
    "parameters": [
      {
        "name": "corroboration_reasoning",
        "type": "reasoning",
        "description": "The reasoning that compares the candidate with the independent metadata value."
      },
      {
        "name": "metadata_observation",
        "type": "observation",
        "description": "The observation containing the metadata value used for the consistency check."
      }
    ],
    "assertion_conditions": [
      "The metadata_observation contains a value that is independent of the candidate's own expression, such as a stored length, size, count, or structural field.",
      "The corroboration_reasoning compares the candidate or its expected properties with that metadata value.",
      "The comparison yields a consistency result that the reasoning uses to corroborate or undermine the candidate."
    ],
    "exclusion_conditions": [
      "The metadata is merely the candidate itself or a direct repetition of it.",
      "The reasoning mentions metadata without comparing it to the candidate.",
      "No consistency conclusion is drawn from the metadata.",
      "The metadata is used to generate a new requirement for an action rather than to check an already proposed candidate."
    ]
  },
  {
    "name": "DERIVES_DECISION_FROM_MEASURED_RESULT",
    "definition": "The reasoning uses quantitative results reported in an observation to compare candidate options or configurations and select or endorse the one with the more favorable measured outcome, or to establish a measured baseline that a subsequent choice or target must improve upon.",
    "parameters": [
      {
        "name": "decision_reasoning",
        "type": "reasoning",
        "description": "The reasoning that compares measured values and makes or endorses a selection, or fixes a numeric baseline for subsequent action."
      },
      {
        "name": "measurement_observation",
        "type": "observation",
        "description": "The observation reporting the measured values used in the comparison or baseline."
      }
    ],
    "assertion_conditions": [
      "The observation reports measured quantities, such as metrics, losses, counts, or comparable numeric outcomes, for at least two candidate options or for a quantity used as a baseline.",
      "The reasoning compares or reuses those quantities to select or endorse a candidate option or to fix a numerical baseline or target for subsequent action."
    ],
    "exclusion_conditions": [
      "The reasoning only repeats the measured numbers without using them to select, endorse, or set a baseline.",
      "The observation contains no measurement relevant to the decision or baseline.",
      "The reasoning selects among options using only qualitative considerations with no measured comparison.",
      "The measurement is used only to check compliance with an already stated external threshold, with no selection among candidates and no baseline derivation."
    ]
  }
]

