["CONFIGURES_EVENT_DRIVEN_AUTOMATION", "PREVENTS_SELF_CAUSED_ADVERSE_EFFECTS_THROUGH_CORRECTIVE_ACTION", "EVALUATES_CANDIDATE_AGAINST_ENUMERATED_CONSTRAINTS_OR_SCENARIOS", "RESOLVES_EVALUATED_CANDIDATE_ELEMENTS_TO_SINGLE_RESULT", "INTERPRETS_REQUIREMENTS_FOR_ACTION_ADMISSIBILITY", "INITIATES_DETACHED_ASYNCHRONOUS_EXECUTION", "REPORTS_ABSENT_OR_UNAVAILABLE_CAPABILITY", "IDENTIFIES_SPECIFIC_POTENTIAL_FAILURE_MODE", "ASSESSES_COMPETING_ACCOUNTS_OF_SAME_OBSERVATION", "ESTABLISHES_EVIDENCE_GROUNDED_TASK_OUTCOME_REFERENCE", "FORMULATES_STRUCTURED_OPERATIVE_ACCOUNT", "SPECIFIES_TARGET_LINKED_CONCRETE_MEANS", "GROUNDS_COMPUTATIONAL_ASSESSMENT_IN_QUANTITATIVE_ANALYSIS", "ANTICIPATES_PROSPECTIVE_VERIFICATION", "DELIMITS_MODIFICATION_AND_RESIDUAL_ARTIFACT_SCOPE", "IDENTIFIES_DEFICIENCY_OR_INCOMPLETENESS", "REPRODUCES_SPECIFIED_PROCEDURE_OR_OPERATION_ORDER", "IMPLEMENTS_LIMITATION_RESPONSIVE_ALTERNATIVE_APPROACH", "EXECUTES_REASONED_REMOVAL_OF_UNWANTED_STATE", "RESOLVES_CANDIDATE_STATUS_FROM_OBSERVED_EVIDENCE", "GROUNDS_REASONING_SPECIFICATION_IN_OBSERVED_ACTION_OR_STATE", "MATERIALIZES_SPECIFIED_CONTENT_IN_DESIGNATED_ARTIFACT", "INTERPRETS_PROBLEMATIC_OBSERVATION_FOR_UNDERSTANDING_OR_RESPONSE"]

Read every member's complete definition, ordered parameters, assertion conditions, and exclusion conditions. Identify the common underlying behavioral mechanism and generate exactly one complete predicate following the system instructions. The new predicate must preserve the cluster arity. Use a unique predicate name that does not conflict with previously generated predicate names. Return only the complete five-field JSON predicate.

message.content:
{
  "name": "GROUNDS_CONSTRAINT_OR_JUDGMENT_IN_OBSERVED_EVIDENCE",
  "definition": "The reasoning extracts or interprets evidence from an observation, including measured values, exact quantitative or formatting properties, related result values, independent metadata, records, or candidate occurrences or fragments, and uses that evidence to derive or establish a constraint, threshold, acceptance criterion, consistency relation, derived quantity, corroboration, selection, or numerical baseline for judging compliance or supporting a subsequent decision.",
  "parameters": [
    {
      "name": "evidence_reasoning",
      "type": "reasoning",
      "description": "The reasoning text that extracts, transforms, compares, or applies content from observed evidence to establish a constraint, requirement, consistency relation, compliance judgment, derived input, selection, or decision baseline."
    },
    {
      "name": "evidence_observation",
      "type": "observation",
      "description": "The observation supplying the measured, quantitative, structural, relational, metadata, record, or candidate content that is used as evidence."
    }
  ],
  "assertion_conditions": [
    "The observation contains identifiable evidence usable by the reasoning, such as numeric measurements, exact properties, related values, metadata, records, or candidate content or context.",
    "The evidence_reasoning explicitly extracts, computes from, compares to, or applies at least one such observed item rather than merely restating it.",
    "The reasoning uses the observed evidence to produce a constraint or requirement, a consistency conclusion, a compliance or violation judgment, corroboration or undermining, a derived quantity, an option selection, or a numerical baseline for a subsequent action or decision."
  ],
  "exclusion_conditions": [
    "The observation supplies only general or qualitative discussion with no identifiable evidence that the reasoning extracts, compares, or applies.",
    "The reasoning merely restates or describes the observation without deriving a constraint, relation, consistency result, judgment, selection, or decision support.",
    "The relevant constraint, comparison, or judgment is based solely on prior knowledge or assumptions rather than on the observation's content.",
    "The observed evidence is mentioned but not used to constrain, accept, corroborate, select among, evaluate a candidate or result, or set a baseline for any outcome.",
    "The reasoning performs an action or reaches a decision independently of the observed evidence."
  ]
}

